	//   - 'i' is the inner (fastest-changing) dimension,
	//   - 'j' is the outer dimension.
	//
	// This layout matches the optimized kernel below, where for a fixed k
	// we traverse:
	//   for each column j (outer),
	//     for each row i (inner, contiguous in memory),
	// which gives:
	//   - contiguous accesses to path[i][j] and path[i][k],
	//   - only one load of path[k][j] per (k, j) pair instead of per (k, i, j).
	DEFINE_PROTO_STRUCT(path_layout, i_vec ^ j_vec);

	// Tuning knobs (currently not used in the kernel, but kept here so that
	// blocking / tiling can be easily experimented with if desired).
	static constexpr std::size_t i_block = 64;
	static constexpr std::size_t j_block = 64;
} tuning;

