// Original C loops:
//
// for (k = 0; k < _PB_N; k++)
//   for (i = 0; i < _PB_N; i++)
//     for (j = 0; j < _PB_N; j++)
//       path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
//                      path[i][j] : path[i][k] + path[k][j];
//
// Optimized version:
// ------------------
// 1) We keep k as the outermost loop (semantics of Floyd–Warshall).
// 2) For each k, we iterate columns j outermost and rows i innermost:
//        for (k)
//          for (j)
//            const num_t p_kj = path[k][j];      // loaded once per (k, j)
//            for (i)
//              const num_t p_ik = path[i][k];    // contiguous in 'i'
//              path[i][j] = min(path[i][j], p_ik + p_kj);
//    This order is semantically equivalent (i/j loops are permutable for
//    a fixed k) and significantly reduces loads of path[k][j] from O(n^3)
//    to O(n^2), while keeping inner-loop accesses contiguous thanks to the
//    column-major layout chosen above.
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		const auto k = get_index<'k'>(sk);

		// For each column j (outer), we traverse all rows i (inner).
		// With the column-major layout (i inner, j outer), this results in
		// contiguous accesses along 'i'.
		traverser(path).template for_dims<'j'>([&](auto tj) {
			// tj has 'j' fixed, 'i' remaining.
			const auto s_j = tj.state();
			const auto j = get_index<'j'>(s_j);

			// path[k][j] is invariant over the inner loop in 'i',
			// so we load it once per (k, j).
			const num_t p_kj = path[noarr::idx<'i', 'j'>(k, j)];

			// Inner loop over all i for the current (k, j)
			tj.for_each([&](auto s_ij) {
				const auto i = get_index<'i'>(s_ij);

				// path[i][k] varies with i, but is contiguous in memory
				// thanks to the column-major layout.
				const num_t p_ik = path[noarr::idx<'i', 'j'>(i, k)];

				num_t &p_ij = path[s_ij];

				const num_t via_k = p_ik + p_kj;
				if (via_k < p_ij)
					p_ij = via_k;
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// build common length descriptor
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto path = noarr::bag(noarr::scalar<num_t>() ^ tuning.path_layout ^ set_lengths);

	// initialize data
	init_array(path.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_floyd_warshall(n, path.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE / correctness checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, path.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

