	// These only affect the *order* in which elements are visited,
	// not the logical index space or the physical layout.
	// They can be tuned for a particular cache hierarchy.
	static constexpr std::size_t block_i = 64; // rows per tile
	static constexpr std::size_t block_j = 64; // columns per tile
} tuning;

// Array initialization: mirrors the original C init_array
void init_array(auto path) {
	using namespace noarr;

	traverser(path).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		num_t value = static_cast<num_t>(i * j % 7 + 1);
		if (((i + j) % 13 == 0) || ((i + j) % 7 == 0) || ((i + j) % 11 == 0))
			value = static_cast<num_t>(999);

		path[state] = value;
	});
}

// Main computational kernel: Floyd–Warshall
// Original C loops:
//
// for (k = 0; k < _PB_N; k++)
//   for (i = 0; i < _PB_N; i++)
//     for (j = 0; j < _PB_N; j++)
//       path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
//                      path[i][j] : path[i][k] + path[k][j];
//
// The implementation below keeps the k-loop outermost and still performs
// exactly one relaxation per (i,j,k) triple, but uses a *tiled* traversal
// over (i,j) for better cache locality. The Floyd–Warshall recurrence is
// order-independent in (i,j) for fixed k, so this reordering preserves
// the algorithm’s semantics.
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Describe a cache-friendly, *tiled* traversal order for the (i,j) space:
	//
	//   - split 'i' into tiles:      I = block index for rows,  i = index inside tile
	//   - split 'j' into tiles:      J = block index for cols,  j = index inside tile
	//   - hoist I and J so that tiles are iterated outermost
	//
	// We use into_blocks_static so that all tiles but the border are full;
	// the border (if any) is handled automatically inside the proto-structure.
	//
	// IMPORTANT: this is only used through traverser(...).order(ij_tiling),
	// which means:
	//   * the *layout* of 'path' stays row-major (j inner, i outer),
	//   * states given to us in the lambda still contain only 'i' and 'j',
	//   * every (i,j) pair is visited exactly once per k.
	const auto ij_tiling =
		noarr::into_blocks_static<'i', '!', 'I', 'i'>(tuning::block_i) ^
		noarr::into_blocks_static<'j', '#', 'J', 'j'>(tuning::block_j) ^
		// Hoist in reverse order so that after both hoists we get:
		//   I outermost, then J, then the remaining dimensions.
		noarr::hoist<'J'>() ^
		noarr::hoist<'I'>();

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([=](auto sk) {
		auto k = get_index<'k'>(sk);

		// Inner loops: tiled traversal over (i,j).
		// This is semantically equivalent to:
		//
		//   for (i = 0; i < n; ++i)
		//     for (j = 0; j < n; ++j)
		//       relax(i,j,k);
		//
		// but the iteration order over (i,j) is block-by-block, which:
		//   - keeps small tiles of the matrix hot in cache,
		//   - improves reuse of path[i][k] and path[k][j] across nearby (i,j),
		//   - preserves the mathematical correctness of Floyd–Warshall.
		traverser(path).order(ij_tiling).for_each([=](auto sij) {
			auto i = get_index<'i'>(sij);
			auto j = get_index<'j'>(sij);

			// States for path[i][k] and path[k][j]
			auto sik = noarr::idx<'i', 'j'>(i, k);
			auto skj = noarr::idx<'i', 'j'>(k, j);

			num_t via_k = path[sik] + path[skj];
			num_t &pij = path[sij];

			// Branchless min is fine, but the ternary is usually compiled
			// to the same code at -O3.
			pij = (pij < via_k) ? pij : via_k;
		});
	});
#pragma endscop
