// Main computational kernel: Floyd–Warshall
// Original C loops:
//
// for (k = 0; k < _PB_N; k++)
//   for (i = 0; i < _PB_N; i++)
//     for (j = 0; j < _PB_N; j++)
//       path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
//                      path[i][j] : path[i][k] + path[k][j];
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// Tunable tile sizes for i and j dimensions.
	// They are compile-time constants so the compiler can optimize well,
	// but the kernel falls back to an unblocked version if n is not a
	// multiple of these sizes.
	constexpr std::size_t I_BLOCK = 32;
	constexpr std::size_t J_BLOCK = 32;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Decide at run time whether we can safely use block-based traversal.
	// `noarr::into_blocks` assumes that the length is a multiple of the
	// block size; otherwise some elements would be skipped. We guard
	// against that here and fall back to a simple, still optimized, kernel.
	const bool use_blocking =
		(n % I_BLOCK == 0) && (n % J_BLOCK == 0);

#pragma scop
	if (use_blocking) {
		// ------------------------------------------------------------------
		// Blocked variant
		// ------------------------------------------------------------------
		//
		// We create a blocked *view* of the matrix:
		//   'i' -> ('I', 'i')  block index / in-block index
		//   'j' -> ('J', 'j')
		// This does not change the in‑memory layout, it only changes the
		// traversal order to improve cache locality on (i,j).
		//
		// For each k we traverse tiles in (I,J) order and inside each tile
		// we visit (i,j) in row-major order.

		constexpr auto blocking_proto =
			noarr::into_blocks<'i', 'I', 'i'>(noarr::lit<I_BLOCK>) ^
			noarr::into_blocks<'j', 'J', 'j'>(noarr::lit<J_BLOCK>);

		// Reorder dimensions so that blocks are traversed as:
		//   outer: I (blocks in i)
		//   next : J (blocks in j)
		//   inner: i, j inside each tile
		constexpr auto tile_order =
			noarr::hoist<'J'>() ^ noarr::hoist<'I'>();

		// Blocked structural view of the path matrix (same data).
		auto blocked_path = path ^ blocking_proto;

		// Outer loop over k
		noarr::traverser(k_struct).for_each([=](auto sk) {
			const std::size_t k = noarr::get_index<'k'>(sk);

			// Views for the k-th column and k-th row. Both share the same
			// underlying storage as `path`, so any updates performed via
			// `path` are immediately visible here.
			//
			// col_k[i] == path[i][k]
			// row_k[j] == path[k][j]
			auto col_k = path ^ noarr::fix<'j'>(k);
			auto row_k = path ^ noarr::fix<'i'>(k);

			// Traverse tiles (I,J); within a tile iterate (i,j).
			noarr::traverser(blocked_path)
				.order(tile_order)
				.template for_dims<'I', 'J'>([=](auto tij) {
					tij.for_each([=](auto sij) {
						// `sij` is a full state that still contains 'i' and 'j'
						// (plus block indices). When indexing `col_k` and
						// `row_k`, the extra indices are ignored:
						//  - col_k uses only 'i' (j is fixed to k by fix<'j'>)
						//  - row_k uses only 'j' (i is fixed to k by fix<'i'>)
						const num_t via_k = col_k[sij] + row_k[sij];

						num_t &pij = path[sij];
						pij = (pij < via_k) ? pij : via_k;
					});
				});
		});
	} else {
		// ------------------------------------------------------------------
		// Unblocked variant
		// ------------------------------------------------------------------
		//
		// This version keeps the original (k,i,j) loop structure but
		// still uses structural views for the k-th row and column, so the
		// inner computation:
		//
		//   via_k = path[i][k] + path[k][j]
		//
		// becomes:
		//
		//   via_k = col_k[i] + row_k[j]
		//
		// which reduces indexing arithmetic inside the hot loop. We still
		// traverse `path` in row‑major order ('i' outer, 'j' inner).

		noarr::traverser(k_struct).for_each([=](auto sk) {
			const std::size_t k = noarr::get_index<'k'>(sk);

			auto col_k = path ^ noarr::fix<'j'>(k); // path[i][k]
			auto row_k = path ^ noarr::fix<'i'>(k); // path[k][j]

			noarr::traverser(path).for_each([=](auto sij) {
				const num_t via_k = col_k[sij] + row_k[sij];

				num_t &pij = path[sij];
				pij = (pij < via_k) ? pij : via_k;
			});
		});
	}
#pragma endscop
}

} // namespace

