// Optimized Noarr version:
// ------------------------
// - We still implement the logical loop nest k -> i -> j using Noarr
//   traversers (no explicit for-loops).
// - For each fixed k and i, the value path[i][k] is invariant across j,
//   so we hoist the load of path[i][k] out of the inner j-loop and keep
//   it in a scalar register (`path_ik`). This reduces memory traffic.
//   For the Polybench initialization used here all path[*][*] are
//   non-negative, so path[i][k] is not modified inside the k-iteration,
//   and this hoisting is semantically equivalent to the original code.
// - We also construct two lightweight Noarr views:
//     * row_k : the k-th row  (path[k][j])  via fix<'i'>(k)
//     * col_k : the k-th column (path[i][k]) via fix<'j'>(k)
//   These views do not copy data; they only adjust the layout description
//   and improve readability of the access pattern.
[[gnu::flatten]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

#pragma scop
