		//  - read path[i][k] once (via `col_k`) and keep it in `path_ik`
		//  - traverse all columns j and update path[i][j]
		//
		// This corresponds to:
		//   for (i = 0; i < n; ++i) {
		//     num_t path_ik = path[i][k];
		//     for (j = 0; j < n; ++j) { ... }
		//   }
