			trav_i.for_each([&](auto state_ij) {
				const std::size_t j = get_index<'j'>(state_ij);

				// path[k][j] read via the k-th row view
				const num_t path_kj = row_k[noarr::idx<'j'>(j)];

				num_t &pij = path[state_ij];
				const num_t via_k = path_ik + path_kj;

				// In-place relaxation
				pij = (pij < via_k) ? pij : via_k;
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// build common length descriptor
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto path = noarr::bag(noarr::scalar<num_t>() ^ tuning.path_layout ^ set_lengths);

	// initialize data
	init_array(path.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

