using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// Tuning constants for the kernel.
// These can be adjusted for a particular target machine if needed.
struct tuning {
	// path[i][j] in C: i = row, j = column, row-major
	// => 'j' inner, 'i' outer
	DEFINE_PROTO_STRUCT(path_layout, j_vec ^ i_vec);

	// Reserved for future tuning (e.g. j-blocking); currently unused but
	// kept here to make experimentation easier.
	static constexpr std::size_t j_block_size = 64;
} tuning;

// Array initialization: mirrors the original C init_array
void init_array(auto path) {
	using namespace noarr;

	// Row-major traversal over (i, j)
	traverser(path).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		num_t value = static_cast<num_t>(i * j % 7 + 1);
		if (((i + j) % 13 == 0) || ((i + j) % 7 == 0) || ((i + j) % 11 == 0))
			value = static_cast<num_t>(999);

		path[state] = value;
	});
}

// Main computational kernel: Floyd–Warshall
// Original C loops:
//
// for (k = 0; k < _PB_N; k++)
//   for (i = 0; i < _PB_N; i++)
//     for (j = 0; j < _PB_N; j++)
//       path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
//                      path[i][j] : path[i][k] + path[k][j];
//
// Optimized Noarr version:
//
// - We still iterate k outermost, then i, then j.
// - For each fixed (k, i) we cache path[i][k] in a scalar before the inner
//   j-loop; this avoids reloading the same column element path[i][k] for
//   every j.
// - For each k we create two lightweight views:
//     * row_k : row view path[k][j]   (fix 'i' = k)
//     * col_k : column view path[i][k] (fix 'j' = k)
//   These are no-copy, layout-preserving views and are cheap to construct.
// - Traversal over (i, j) is expressed using a traverser with for_dims<'i'>
//   so that we get an explicit "row loop" where we can perform the hoisting.
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Pre-constructed traverser over the 2D matrix (i, j); reused for each k.
	const auto trav_ij = traverser(path);

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

		// Views for the current intermediate vertex k:
		//   row_k[j] == path[k][j]
		//   col_k[i] == path[i][k]
		//
		// These are layout-preserving bag views created with `fix`. They do
		// not allocate or copy data; they only modify how indices are
		// interpreted.
		auto row_k = path ^ noarr::fix<'i'>(k); // dimension: 'j'
		auto col_k = path ^ noarr::fix<'j'>(k); // dimension: 'i'

		// Middle and inner loops over i, j in row-major order:
		// - for_dims<'i'> gives us one traverser per row i
		// - trav_i.for_each iterates j inside that row
		trav_ij.template for_dims<'i'>([&](auto trav_i) {
			// Extract the fixed row index i from the row-level traverser.
			auto s_i = trav_i.state();
			const std::size_t i = get_index<'i'>(s_i);

			// Hoist path[i][k] out of the inner j-loop. This value is
			// invariant across all j for the fixed (k, i) and is not
			// modified within the k-iteration (even when j == k the update
			// is a no-op), so this transformation is semantics-preserving.
			const num_t path_ik = col_k[noarr::idx<'i'>(i)];

			// Inner loop over j for this row i
			trav_i.for_each([&](auto sij) {
				const std::size_t j = get_index<'j'>(sij);

				// path[k][j] read via the row view; contiguous in memory as j varies.
				const num_t path_kj = row_k[noarr::idx<'j'>(j)];

				const num_t via_k = path_ik + path_kj;

				// Reference to path[i][j]; sij encodes (i, j).
				num_t &pij = path[sij];

				pij = (pij < via_k) ? pij : via_k;
			});
		});
	});
#pragma endscop
}

} // namespace

